  "servers.multicore.reason.vanilla": "To jest vanilla, która nie obsługuje modów. Mody wymagają loadera modów, np. Fabric lub NeoForge. ResinCraft nie przerobi tego za ciebie: zamiast tego utwórz nową instancję lub nowy serwer z loaderem modów.",
  "servers.multicore.reason.noLoader": "Ten loader jest za stary dla tych modów. Wymagają one Fabric, Quilt, NeoForge lub Forge.",
  "servers.multicore.reason.noMods": "Żaden z tych modów nie ma wersji dla tego loadera i tej wersji Minecraft, więc nie ma czego instalować.",
  "servers.multicore.reason.plugins": "Pluginy nie mogą rozłożyć ticku na wiele rdzeni: działają w głównym wątku serwera. Paper już wykonuje pracę na chunkach na innych rdzeniach. Jedynym sposobem, by sam tick działał na kilku rdzeniach, jest zmiana oprogramowania serwera na Folię.",
  "servers.multicore.reason.hybrid": "Arclight łączy mody i pluginy, a te mody zmieniają ten sam kod co on. Nie są tu bezpieczne, więc nic nie jest proponowane.",
  "servers.multicore.reason.bedrock": "Serwery Bedrock to osobny program, który nie obsługuje modów ani pluginów Javy, więc nie ma czego konfigurować.",
  "servers.multicore.reason.folia": "Ten serwer działa na Folii, która już obsługuje osobne regiony świata na osobnych rdzeniach.",
  "servers.multicore.reason.noJavaMods": "To oprogramowanie serwera nie obsługuje modów Fabric, Quilt, NeoForge ani Forge, więc nie ma czego konfigurować.",
  "servers.multicore.folia.title": "Przejdź na Folię (opcjonalnie)",
  "servers.multicore.folia.warning": "Folia obsługuje osobne regiony świata na osobnych rdzeniach, więc pomaga tylko wtedy, gdy gracze są rozproszeni, a jej twórcy zalecają co najmniej 16 rdzeni. Wiele pluginów na niej nie działa. To zmienia oprogramowanie serwera, więc rób to tylko wtedy, gdy sprawdzisz swoje pluginy.",
